"use client";

/**
 * Screenshot capture: a browser window is captured while a toast counts to
 * 100 percent, then the window shrinks and drops away and the toast turns
 * into a confirmation with a check.
 *
 * Written by Better Design. Painted from the theme prop; with no picture the
 * window shows a placeholder page drawn from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

/** Timing, in frames. */
const TOAST_AT = 12;
const COUNT_AT = 20;
const COUNT_FRAMES = 46;
const DROP_AT = 68;
const DONE_AT = 72;
const RING = 30;

export interface ScreenshotCaptureProps {
  /** What the toast says while it captures. */
  label?: string;
  /** What the toast says once the capture lands. */
  done?: string;
  /** Image for the window. Drawn as a placeholder page when absent. */
  src?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function PlaceholderPage({ theme }: { theme: VideoTheme }) {
  const bar = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />;
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, padding: "56px 64px", display: "flex", flexDirection: "column", gap: 34 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ width: 36, height: 36, borderRadius: 10, background: theme.primary }} />
        <div style={{ display: "flex", gap: 28 }}>{[90, 70, 80].map((w, i) => <div key={i} style={{ width: w, height: 12, borderRadius: 6, background: withAlpha(theme.foreground, 0.2) }} />)}</div>
      </div>
      <div style={{ display: "flex", gap: 48, flex: 1 }}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", gap: 22 }}>
          {bar("86%", 44, withAlpha(theme.foreground, 0.8))}
          {bar("62%", 44, withAlpha(theme.foreground, 0.8))}
          {bar("74%", 14)}
          {bar("56%", 14)}
          <div style={{ width: 180, height: 54, borderRadius: 27, background: theme.primary, marginTop: 10 }} />
        </div>
        <div style={{ flex: 1, borderRadius: 22, background: `linear-gradient(150deg, ${withAlpha(theme.primary, 0.4)}, ${withAlpha(theme.primary, 0.08)})`, border: `1px solid ${theme.border}` }} />
      </div>
    </div>
  );
}

/** A window captured while a toast counts to 100, then confirms the copy. */
export function ScreenshotCapture({
  label = "Capturing selection",
  done = "Copied to clipboard",
  src,
  theme: themeOverride,
  font,
}: ScreenshotCaptureProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const enter = easings.out(progress(frame, 0, 16));
  const pct = easings.inOut(progress(frame, COUNT_AT, COUNT_FRAMES));
  const drop = easings.in(progress(frame, DROP_AT, 22));
  const shrink = easings.out(progress(frame, DROP_AT - 6, 14));
  const flash = interpolate(frame, [COUNT_AT + COUNT_FRAMES - 2, COUNT_AT + COUNT_FRAMES + 2, COUNT_AT + COUNT_FRAMES + 12], [0, 0.5, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const toastIn = spring({ frame: frame - TOAST_AT, fps, config: springs.snappy });
  const doneT = easings.out(progress(frame, DONE_AT, 14));
  const pop = spring({ frame: frame - DONE_AT, fps, config: springs.bouncy });
  const capturing = frame < DONE_AT;
  // Once the window is gone, the toast rises to the centre and holds the end of the shot.
  const rise = easings.inOut(progress(frame, DONE_AT + 4, 24));

  const circumference = 2 * Math.PI * (RING / 2 - 3);

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          position: "absolute",
          top: 110,
          width: 1280,
          height: 760,
          borderRadius: theme.radius * 1.5,
          overflow: "hidden",
          background: theme.card,
          border: `1px solid ${theme.border}`,
          boxShadow: "0 50px 120px oklch(0 0 0 / 0.16)",
          opacity: enter * (1 - drop),
          transform: `translateY(${(1 - enter) * 30 + drop * 520}px) scale(${1 - shrink * 0.42}) rotate(${drop * -4}deg)`,
          transformOrigin: "50% 60%",
        }}
      >
        <div style={{ height: 52, display: "flex", alignItems: "center", gap: 10, padding: "0 20px", background: theme.muted, borderBottom: `1px solid ${theme.border}` }}>
          {[0, 1, 2].map((i) => (
            <div key={i} style={{ width: 13, height: 13, borderRadius: 7, background: withAlpha(theme.foreground, 0.16) }} />
          ))}
          <div style={{ marginLeft: 220, width: 520, height: 28, borderRadius: 14, background: theme.card, border: `1px solid ${theme.border}` }} />
        </div>
        <div style={{ position: "absolute", top: 52, left: 0, right: 0, bottom: 0 }}>
          {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <PlaceholderPage theme={theme} />}
          {/* The selection: a ring that tightens as the capture runs, then a white flash. */}
          <div style={{ position: "absolute", inset: 18, borderRadius: theme.radius, border: `3px solid ${withAlpha(theme.primary, 0.9 * Math.min(1, toastIn))}`, boxShadow: `0 0 0 9999px ${withAlpha(theme.primary, 0.06 * (1 - pct))}` }} />
          <div style={{ position: "absolute", inset: 0, background: "oklch(1 0 0)", opacity: flash }} />
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          bottom: 96,
          display: "flex",
          alignItems: "center",
          gap: 20,
          padding: "20px 34px 20px 22px",
          borderRadius: 999,
          background: theme.popover,
          border: `1px solid ${theme.border}`,
          boxShadow: "0 24px 60px oklch(0 0 0 / 0.18)",
          color: theme.popoverForeground,
          fontSize: 32,
          fontWeight: 600,
          opacity: Math.min(1, toastIn),
          transform: `translateY(${(1 - toastIn) * 60 - rise * 404}px) scale(${(capturing ? 1 : 0.96 + pop * 0.04) * (1 + rise * 0.3)})`,
        }}
      >
        {capturing ? (
          <svg width={RING} height={RING} style={{ transform: "rotate(-90deg)" }}>
            <circle cx={RING / 2} cy={RING / 2} r={RING / 2 - 3} fill="none" stroke={withAlpha(theme.foreground, 0.12)} strokeWidth={4} />
            <circle cx={RING / 2} cy={RING / 2} r={RING / 2 - 3} fill="none" stroke={theme.primary} strokeWidth={4} strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={circumference * (1 - pct)} />
          </svg>
        ) : (
          <div style={{ width: RING + 6, height: RING + 6, borderRadius: "50%", background: theme.primary, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop})` }}>
            <svg width={20} height={20} viewBox="0 0 20 20">
              <path d="M4 10.5 L8.2 14.5 L16 6" fill="none" stroke={theme.primaryForeground} strokeWidth={2.8} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={20} strokeDashoffset={20 * (1 - doneT)} />
            </svg>
          </div>
        )}
        <span style={{ opacity: capturing ? 1 : doneT }}>{capturing ? label : done}</span>
        {capturing ? (
          <span style={{ color: theme.mutedForeground, fontVariantNumeric: "tabular-nums", minWidth: 80, textAlign: "right" }}>{Math.round(pct * 100)}%</span>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}
